layer.css:
[data-ryt="pitch"] { color: #767b7f; border-left: 4px solid rgb(238, 238, 238); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 14.6667px; font-weight: 300; font-style: italic; line-height: 2.375; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(33, 41, 49); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.33333px; padding-right: 0px; padding-bottom: 7.33333px; padding-left: 29.3333px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { background-color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none; color: var(--ryt-bg) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #767b7f; border-bottom: 1px dotted rgba(33, 41, 49, 0.5); border-radius: 0px; font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(33, 41, 49); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.2s ease-in-out, background-color 0.2s ease-in-out, border-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: #767b7f; font-family: var(--ryt-font-heading); font-size: 56px; font-weight: 900; font-style: normal; line-height: 1.1; letter-spacing: 4.4px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(33, 41, 49); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: #74787d; border-bottom: 1px dotted rgba(255, 255, 255, 0.5); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 11.7333px; font-weight: 900; font-style: normal; line-height: 5; letter-spacing: 1.1px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.2s ease-in-out, color 0.2s ease-in-out; border-top: none; border-right: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"] { color: #767b7f; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 900; font-style: normal; line-height: 1.1; letter-spacing: 4.4px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(33, 41, 49); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"]:hover { border-bottom-color: transparent; border-bottom-color: transparent; color: rgb(24, 191, 239); border-bottom-color: transparent; color: rgb(24, 191, 239); color: inherit; background-color: rgba(255, 255, 255, 0.1); color: rgb(24, 191, 239) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { border-bottom-color: transparent; border-bottom-color: transparent; color: rgb(24, 191, 239) }
